insert into settings (key, value, description) values
  ('vod.max_concurrent', '1'::jsonb, 'Videos the VOD lane processes at the same time. A job over the limit waits vod.concurrency_retry_s.'),
  ('vod.concurrency_retry_s', '120'::jsonb, 'Seconds a vod.process job waits when vod.max_concurrent videos are already being processed.'),
  ('vod.processing_stale_s', '7200'::jsonb, 'A video in status processing that was not updated for this long no longer counts as being processed (its worker died).'),
