  ('vod.clipped_range_margin_s', '30'::jsonb, 'Replay pass after a live stream: spikes closer than this to a range the live lane already clipped are dropped.'),
  ('vod.chat_retry_delay_s', '20'::jsonb, 'Seconds before the single retry when YouTube reports no chat replay for a past stream.'),
  ('vod.confirm_with_captions', 'true'::jsonb, 'Fetch the caption track (no media) and show the words around each spike to the confirmation prompt.'),
  ('vod.caption_langs', '[".*-orig", "en"]'::jsonb, 'Caption tracks asked for, in order of preference: language codes or patterns (.*-orig is the automatic track in the language spoken).'),
  ('vod.caption_timeout_s', '180'::jsonb, 'Seconds before the yt-dlp caption download is killed.'),
  ('vod.download_timeout_s', '900'::jsonb, 'Seconds before one yt-dlp window download is killed.'),
  ('vod.download_failures_max', '3'::jsonb, 'Failed window downloads in a row after which the video is given up for this attempt.'),
